def load_entity_codes() -> list[str]:
    text = (ROOT / "embedded-data.js").read_text(encoding="utf-8")
    prefix = "window.MARKET_BASE_EMBEDDED_DATA = "
    if not text.startswith(prefix):
        raise RuntimeError("Unexpected embedded-data.js format")
    payload = text[len(prefix):].rstrip().rstrip(";")
    data = json.loads(payload)
    return [row["entity_id"] for row in data["entities"]["entities"]]


def main() -> None:
    entity_codes = load_entity_codes()
    missing = [code for code in entity_codes if code not in FACTS]
    extra = [code for code in FACTS if code not in entity_codes]
    if missing or extra:
        raise SystemExit(f"coverage error: missing={missing}, extra={extra}")

    ordered = {code: FACTS[code] for code in entity_codes}
    payload = {
        "version": "MARKET_BASE_COUNTRY_DISTINCTIVE_FACTS_V333_15_20260809",
        "updated": "2026-08-09",
        "count": len(ordered),
        "items": ordered,
    }
    content = (
        "/* MARKET BASE V333.15: one distinctive, system-oriented fact for each of the 196 country/area profiles. */\n"
        "(function (global) {\n"
        "  'use strict';\n"
        f"  global.MARKET_BASE_COUNTRY_DISTINCTIVE_FACTS = Object.freeze({json.dumps(payload, ensure_ascii=False, separators=(',', ':'))});\n"
        "})(window);\n"
    )
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(content, encoding="utf-8")
    print(json.dumps({"output": str(OUTPUT.relative_to(ROOT)), "count": len(ordered)}, ensure_ascii=False))


if __name__ == "__main__":
    main()
